components.draw:
const w = softmax(state.E.map((e) => dot(state.E[state.q], e) / Math.sqrt(3)), state.temp);
return [
  sequence(state.tokens, { id: 'query', label: 'query', highlight: [state.q], links: w.map((v, j) => [state.q, j, round(v, 3)]) }),
  sequence(state.tokens, { id: 'keys', label: 'keys', values: w.map((v) => round(v, 2)) })
];
